import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 12;

// Three channels — random-feeling numbers, all starting around 500k subs.
// Ratio = views / subs. We triple that ratio over the animation.
const CHANNELS = [
  {
    id: "ch1",
    subsStart: 487000,
    subsEnd: 512000,
    viewsStart: 612000,    // ratio ≈ 1.25
    viewsEnd: 1968000,     // ratio ≈ 3.84  (3.07×)
    avatarHue: 18,
  },
  {
    id: "ch2",
    subsStart: 523000,
    subsEnd: 548000,
    viewsStart: 731000,    // ratio ≈ 1.40
    viewsEnd: 2410000,     // ratio ≈ 4.40  (3.14×)
    avatarHue: 200,
  },
  {
    id: "ch3",
    subsStart: 461000,
    subsEnd: 489000,
    viewsStart: 558000,    // ratio ≈ 1.21
    viewsEnd: 1816000,     // ratio ≈ 3.71  (3.07×)
    avatarHue: 280,
  },
];

const SCENE_DUR = 220;
const TOTAL = SCENE_DUR;

export const durationInFrames = TOTAL;

// Format a number like 487,000 or 1.97M
function formatNum(n: number): string {
  if (n >= 1_000_000) {
    const m = n / 1_000_000;
    return `${m.toFixed(2)}M`;
  }
  if (n >= 1_000) {
    return `${Math.round(n / 1000)}K`;
  }
  return String(Math.round(n));
}

// Simple play-button SVG (YouTube-ish, but generic — no brand)
const PlayGlyph: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <rect x="2" y="5" width="20" height="14" rx="4" fill={color} />
    <path d="M10 9 L16 12 L10 15 Z" fill={COLORS.card} />
  </svg>
);

// Tiny eye glyph for views
const EyeGlyph: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <path
      d="M2 12 C5 6, 10 4, 12 4 C14 4, 19 6, 22 12 C19 18, 14 20, 12 20 C10 20, 5 18, 2 12 Z"
      stroke={color}
      strokeWidth={2.2}
      fill="none"
      strokeLinejoin="round"
    />
    <circle cx="12" cy="12" r="3" fill={color} />
  </svg>
);

// Tiny person glyph for subs
const PersonGlyph: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle cx="12" cy="8" r="4" fill={color} />
    <path
      d="M4 20 C4 15, 8 13, 12 13 C16 13, 20 15, 20 20"
      stroke={color}
      strokeWidth={2.4}
      fill="none"
      strokeLinecap="round"
    />
  </svg>
);

// Avatar circle (simple colored disc with monogram-style inner ring)
const Avatar: React.FC<{ size: number; hue: number }> = ({ size, hue }) => {
  const c1 = `hsl(${hue}, 70%, 55%)`;
  const c2 = `hsl(${hue}, 70%, 40%)`;
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        background: `linear-gradient(135deg, ${c1}, ${c2})`,
        flexShrink: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        boxShadow: `0 0 0 4px ${COLORS.card}, 0 0 0 5px ${COLORS.border}`,
      }}
    >
      <PlayGlyph size={size * 0.5} color={"#fff"} />
    </div>
  );
};

type Channel = (typeof CHANNELS)[number];

const ChannelCard: React.FC<{
  channel: Channel;
  index: number;
}> = ({ channel, index }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Entrance — staggered, LIQUID for premium settle.
  const cardIn = staggeredSpring(
    frame,
    vfps,
    index,
    TIMING.entrance,
    TIMING.staggerItem + 4,
    "LIQUID",
  );

  // The big count-up: starts a bit after the card lands.
  // We use a slow LIQUID spring so numbers feel like they "climb".
  const countDelay = TIMING.entrance + 20 + index * 6;
  const countProgress = spring({
    frame,
    fps: vfps,
    delay: countDelay,
    config: SPRINGS.LIQUID,
  });

  // Ratio-bar reveal — comes in just after numbers start moving.
  const barIn = springIn(frame, vfps, countDelay + 10, "GENTLE");

  // Multiplier badge — pops in near the end, ELASTIC.
  const badgeIn = springIn(frame, vfps, countDelay + 70, "ELASTIC");

  // Ambient breathing
  const driftY = ambientDrift(frame, 2.2, 110 + index * 18, `card-${channel.id}`);

  // Animated values
  const subs = Math.round(
    interpolate(countProgress, [0, 1], [channel.subsStart, channel.subsEnd]),
  );
  const views = Math.round(
    interpolate(countProgress, [0, 1], [channel.viewsStart, channel.viewsEnd]),
  );

  const ratioStart = channel.viewsStart / channel.subsStart;
  const ratioEnd = channel.viewsEnd / channel.subsEnd;
  const ratioNow = ratioStart + (ratioEnd - ratioStart) * countProgress;
  const multiplier = ratioNow / ratioStart;

  // Bar fill 0..1 — normalize against ratioEnd so it fills to ~100% at end.
  const barFill = Math.min(1, ratioNow / ratioEnd) * barIn;

  // Card transform
  const tx = interpolate(cardIn, [0, 1], [60, 0]);
  const sc = interpolate(cardIn, [0, 1], [0.94, 1]);
  const bl = interpolate(cardIn, [0, 1], [10, 0]);

  return (
    <div
      style={{
        opacity: cardIn,
        transform: `translateY(${tx + driftY}px) scale(${sc})`,
        filter: `blur(${bl}px)`,
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 36,
        padding: "56px 64px",
        display: "flex",
        flexDirection: "column",
        gap: 40,
        width: "100%",
        boxShadow: "0 32px 96px rgba(0,0,0,0.45)",
      }}
    >
      {/* Top row: avatar + (subs / views columns) + multiplier badge */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 56,
        }}
      >
        <Avatar size={160} hue={channel.avatarHue} />

        {/* Subs column */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 14,
            minWidth: 320,
            fontFamily: BRAND.fonts.marketing,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
              color: COLORS.textSubtle,
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 400,
              fontSize: 34,
              letterSpacing: "0.02em",
            }}
          >
            <PersonGlyph size={36} color={COLORS.textSubtle} />
            <span>subscribers</span>
          </div>
          <div
            style={{
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 600,
              fontSize: 90,
              color: COLORS.text,
              letterSpacing: "-0.025em",
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {formatNum(subs)}
          </div>
        </div>

        {/* Views column */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 14,
            minWidth: 320,
            fontFamily: BRAND.fonts.marketing,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
              color: COLORS.orange,
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 400,
              fontSize: 34,
              letterSpacing: "0.02em",
            }}
          >
            <EyeGlyph size={36} color={COLORS.orange} />
            <span>views</span>
          </div>
          <div
            style={{
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 600,
              fontSize: 90,
              color: COLORS.orange,
              letterSpacing: "-0.025em",
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {formatNum(views)}
          </div>
        </div>

        {/* spacer */}
        <div style={{ flex: 1 }} />

        {/* Multiplier badge */}
        <div
          style={{
            opacity: badgeIn,
            transform: `scale(${interpolate(badgeIn, [0, 1], [0.6, 1])}) rotate(${interpolate(
              badgeIn,
              [0, 1],
              [-8, 0],
            )}deg)`,
            backgroundColor: COLORS.card,
            border: `3px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: "20px 44px",
            display: "flex",
            alignItems: "baseline",
            gap: 6,
            fontFamily: BRAND.fonts.marketing,
          }}
        >
          <span
            style={{
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 600,
              fontSize: 74,
              color: COLORS.orange,
              lineHeight: 1,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {multiplier.toFixed(2)}
          </span>
          <span
            style={{
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 600,
              fontSize: 48,
              color: COLORS.orange,
              lineHeight: 1,
            }}
          >
            ×
          </span>
        </div>
      </div>

      {/* Ratio bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 24,
        }}
      >
        {/* Track — sits inside the opaque card, so low-alpha is fine here */}
        <div
          style={{
            flex: 1,
            height: 28,
            backgroundColor: "rgba(255,255,255,0.06)",
            borderRadius: 14,
            overflow: "hidden",
            border: `1px solid ${COLORS.border}`,
          }}
        >
          <div
            style={{
              width: `${barFill * 100}%`,
              height: "100%",
              background: `linear-gradient(90deg, ${COLORS.orangeDeep}, ${COLORS.orange})`,
              borderRadius: 14,
              boxShadow: `0 0 24px ${COLORS.orange}`,
            }}
          />
        </div>
        {/* Ratio readout */}
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: 38,
            color: COLORS.textMuted,
            letterSpacing: "-0.01em",
            fontVariantNumeric: "tabular-nums",
            minWidth: 200,
            textAlign: "right",
            opacity: barIn,
          }}
        >
          <span style={{ color: COLORS.text }}>{ratioNow.toFixed(2)}</span>
          <span style={{ color: COLORS.textSubtle, fontSize: 28, marginLeft: 10 }}>
            views/sub
          </span>
        </div>
      </div>
    </div>
  );
};

const ChannelsScene: React.FC = () => {
  return (
    <AbsoluteFill
      style={{
        padding: "120px 180px",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        gap: 56,
        fontFamily: BRAND.fonts.marketing,
      }}
    >
      {CHANNELS.map((ch, i) => (
        <ChannelCard key={ch.id} channel={ch} index={i} />
      ))}
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_DUR}>
        <ChannelsScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
